'use strict';
// Non-destructive subject browsing. Suggested matches are not verified STCW mappings.
const ctTracks={nw:{title:'OIC-NW · Operational',bank:'nw',groups:learningCompetencies.nw},ew:{title:'OIC-EW · Operational',bank:'ew',groups:learningCompetencies.ew},'mlc-nw':{title:'MLC Deck · Management',bank:'mlc-nw',groups:[['Voyage planning','Position and compass accuracy','Search and rescue','Watchkeeping and bridge teamwork','Radar and navigation systems','ECDIS management','Weather and oceanographic conditions','Navigational emergencies','Ship manoeuvring','Propulsion and engineering controls'],['Cargo planning and safe carriage','Cargo space and ballast tank damage','Dangerous goods'],['Trim, stability and stress','Legislative compliance and environment','Safety and security','Emergency and damage control plans','Leadership and management'] ]},gmdss:{title:'GMDSS GOC',bank:'nw',groups:[['Transmit and receive information using GMDSS subsystems','Provide radio services in emergencies']]}};
const ctKeywords={ 'Transmit and receive information using GMDSS subsystems':['gmdss','dsc','navtex','inmarsat','radio frequency','radio communication'], 'Provide radio services in emergencies':['mayday','epirb','sart','distress alert','radio distress']};
let ctTrack='nw',ctSelection=-1,ctQuery='',ctLimit=25,ctEpoch=0;
function ctEntries(){let n=0;return ctTracks[ctTrack].groups.flatMap((g,f)=>g.map(title=>({title,function:f+1,index:n++})))}
function ctTerms(title){return ctKeywords[title]||title.toLowerCase().split(/[^a-z]+/).filter(w=>w.length>4&&!['using','systems','equipment','management','planning','control','maintain','safety','requirements','procedures','operations','marine','shipboard'].includes(w))}
function ctMatches(q,entry){const text=q.question.toLowerCase();return ctTerms(entry.title).some(w=>text.includes(w))}
function ctPool(){const bank=lhBankNow(),entries=ctEntries();return bank.questions.filter(q=>ctSelection===-1?(ctTrack!=='gmdss'||entries.some(e=>ctMatches(q,e))):ctSelection===-2?!entries.some(e=>ctMatches(q,e)):ctMatches(q,entries[ctSelection]))}
function ctCards(){return `<div class="lh-exam-grid">${Object.entries(ctTracks).map(([id,t])=>`<button class="card lh-exam-card" data-ct-track="${id}"><span class="lh-level">Competence browser</span><h2>${t.title}</h2><p>Functions · study · practice</p></button>`).join('')}<section class="card"><h2>MLC Engine</h2><p>Reserved · Coming soon</p></section></div>`}
const ctOldExams=lhExams;lhExams=function(){ctOldExams();app.insertAdjacentHTML('afterbegin',`<section><h2>Explore by competence</h2>${ctCards()}<p class="hint">Subject matches are suggested, pending technical review. Original source banks remain below.</p></section>`)};
const ctOldStudy=lhStudyLanding;lhStudyLanding=function(){ctOldStudy();app.insertAdjacentHTML('beforeend',`<h2>Officer tracks</h2>${ctCards()}`)};
async function ctOpen(id){const epoch=++ctEpoch;ctTrack=id;ctSelection=-1;ctQuery='';ctLimit=25;await lhOpenBank(ctTracks[id].bank,'setup');if(epoch!==ctEpoch||lhScreen==='error')return;lhScreen='competence';render()}
function ctView(){const t=ctTracks[ctTrack],entries=ctEntries(),bank=lhBankNow();app.innerHTML=lhHead(t.title,'exams','Toolbox practice · not an official examination')+`<p class="lh-source-note">Suggested subject matches, not verified competence assignments. A question may appear in more than one subject. GMDSS currently uses relevant questions from the OIC-NW source; it is not a complete GOC bank.</p><label class="field">Function and competence<select id="ctSelect"><option value="-1">All source questions · ${bank.questions.length}</option><option value="-2">Awaiting competence mapping</option>${entries.map(e=>`<option value="${e.index}" ${ctSelection===e.index?'selected':''}>F${e.function} · ${esc(e.title)}</option>`).join('')}</select></label><label class="search"><input id="ctSearch" type="search" aria-label="Search competence questions" placeholder="Find a question or answer" value="${esc(ctQuery)}"></label><div id="ctResults"></div>`;document.getElementById('ctSelect').value=String(ctSelection);document.getElementById('ctSelect').onchange=e=>{ctSelection=Number(e.target.value);ctLimit=25;ctResults()};document.getElementById('ctSearch').oninput=e=>{ctQuery=e.target.value;ctLimit=25;ctResults()};ctResults()}
function ctResults(){const pool=ctPool(),qs=pool.filter(q=>(q.question+' '+q.options.join(' ')).toLowerCase().includes(ctQuery.toLowerCase())),eligible=pool.filter(q=>lhCorrect(q).length&&!q.keyWarning&&!q.needsFigure);document.getElementById('ctResults').innerHTML=`<p role="status">${qs.length} questions shown by this search · ${eligible.length} eligible for source-key scoring in this selection</p><div class="career-actions"><button class="btn" data-ct-start="practice" ${eligible.length?'':'disabled'}>Practise up to 10</button><button class="btn quiet" data-ct-start="mock" ${eligible.length?'':'disabled'}>Timed practice · up to 20</button></div><p class="hint">Timed practice allows one minute per selected question. This is a Toolbox setting, not an official exam rule. Questions without keys remain readable below.</p>${qs.slice(0,ctLimit).map(q=>`<details class="card"><summary>Q${q.number} · ${esc(q.question)}</summary><ol>${q.options.map(o=>`<li>${esc(o)}</li>`).join('')}</ol><p>${lhCorrect(q).length?'Source-marked answer: '+lhCorrect(q).map(i=>esc(q.options[i])).join('; '):'Answer key missing — unscored study only.'}</p>${lhSource(q,lhBankNow())}</details>`).join('')||'<p>No matching questions. All source questions remain available.</p>'}${qs.length>ctLimit?'<button class="btn quiet" data-ct-more>Show more</button>':''}`}
const ctOldReview=reviewView;reviewView=function(){if(lhScreen==='competence')ctView();else ctOldReview()};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.ctTrack){void ctOpen(b.dataset.ctTrack);return}if(b.hasAttribute('data-ct-more')){ctLimit+=25;ctResults();return}if(b.dataset.ctStart){const pool=ctPool().filter(q=>lhCorrect(q).length&&!q.keyWarning&&!q.needsFigure&&!state.review.flagged.includes(q.id));if(!pool.length)return;const mode=b.dataset.ctStart;lhSetup={mode,count:mode==='mock'?20:10,minutes:Math.min(20,pool.length),topic:''};const original=lhExamPool;lhExamPool=()=>pool;try{lhStart()}finally{lhExamPool=original}}});
